public class Solution {
    public static int sumAlt(int[] arr) {
        // CONTRACT: arr[0] - arr[1] + arr[2] - arr[3] + ...
        int total = 0;
        for (int i = 0; i < arr.length; i++) {
            if (i % 2 == 0) {
                total += arr[i];
            } else {
                total += arr[i];
            }
        }
        return total;
    }
}

